const { parseTRC } = require('../trc');

const HEAD = [
  ';$FILEVERSION=2.0',
  ';$COLUMNS=N,O,T,I,d,l,D',
  ';   Start time: 10/25/2022 10:00:00.000.0',
  ';   Generated by PCAN-View v4.3.3.90'
].join('\n');

describe('trc.js — PCAN-View .trc 解析', () => {
  it('解析数据行（N,O,T,I,d,l,D）并归一化为秒', () => {
    const text = [
      HEAD,
      '     1        83.901 FB     07A0 Rx 64 FD 00 00 00 00 00 00 00',
      '     2        84.901 FB     07A1 Rx 64 FF 01 02 03 00 00 00 00'
    ].join('\n');
    const r = parseTRC(text);
    expect(r.parseErrorCount).toBe(0);
    expect(r.messages).toHaveLength(2);
    const [a, b] = r.messages;
    expect(a.id).toBe(0x7a0);
    expect(a.timestamp).toBeCloseTo(0.083901, 6);
    expect(a.direction).toBe('Rx');
    expect(a.isFd).toBe(true); // dlc 64 > 8
    expect(a.isExtended).toBe(false); // 0x7a0 = 1952 < 0x7ff(2047)
    expect(a.data[0]).toBe(0xfd);
    expect(b.id).toBe(0x7a1);
    expect(b.data[0]).toBe(0xff);
  });

  it('头部注释进 headerLines 且不计错误', () => {
    const r = parseTRC(HEAD + '\n     1        1.000 FB     07A0 Rx 8 01 02 03 04 05 06 07 08\n');
    expect(r.headerLines).toHaveLength(4);
    expect(r.parseErrorCount).toBe(0);
    expect(r.messages).toHaveLength(1);
  });

  it('PCAN 状态行（ST）单列统计，不记为解析错误', () => {
    const r = parseTRC('80803    106832.043 ST          Rx    00 00 00 08\n');
    expect(r.messages).toHaveLength(0);
    expect(r.parseErrorCount).toBe(0);
    expect(r.statusLines).toBe(1);
  });

  it('格式不识别行计入容错', () => {
    const r = parseTRC('garbage line\n');
    expect(r.parseErrorCount).toBe(1);
    expect(r.parseErrors[0].reason).toContain('格式不识别');
  });

  it('数据长度按 l 列截断', () => {
    const r = parseTRC('     1        1.000 FB     0100 Rx 4 AA BB CC DD\n');
    expect(r.messages[0].dlc).toBe(4);
    expect(r.messages[0].data).toEqual([0xaa, 0xbb, 0xcc, 0xdd]);
  });
});
